const STORE_KEY = 'form-workout-data-v2';
const OLD_KEY = 'form-workout-data-v1';
const ROUTINE_DRAFT_KEY = 'form-routine-draft-v1';
const todayISO = () => { const d=new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
const uid = () => globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`;
const DEFAULT_LIBRARY = [
  ['Bench Press','Chest'],['Incline Dumbbell Press','Chest'],['Dumbbell Fly','Chest'],['Cable Fly','Chest'],['Push-up','Chest'],['Chest Press Machine','Chest'],
  ['Overhead Press','Shoulders'],['Dumbbell Shoulder Press','Shoulders'],['Lateral Raise','Shoulders'],['Rear Delt Fly','Shoulders'],['Face Pull','Shoulders'],
  ['Pull-up','Back'],['Lat Pulldown','Back'],['Barbell Row','Back'],['Seated Cable Row','Back'],['Single-arm Dumbbell Row','Back'],['Deadlift','Back'],['Back Extension','Back'],
  ['Barbell Curl','Arms'],['Dumbbell Curl','Arms'],['Hammer Curl','Arms'],['Triceps Pushdown','Arms'],['Overhead Triceps Extension','Arms'],['Skull Crusher','Arms'],
  ['Barbell Squat','Legs'],['Leg Press','Legs'],['Romanian Deadlift','Legs'],['Leg Extension','Legs'],['Leg Curl','Legs'],['Walking Lunge','Legs'],['Hip Thrust','Legs'],['Calf Raise','Legs'],
  ['Plank','Core'],['Hanging Leg Raise','Core'],['Cable Crunch','Core'],['Treadmill','Cardio'],['Stationary Bike','Cardio'],['Rowing Machine','Cardio']
].map(([name,category])=>({id:`lib-${name.toLowerCase().replace(/[^a-z0-9]+/g,'-')}`,name,category,custom:false}));
const freshData = () => ({version:2,routines:[],workouts:[],weighIns:[],customExercises:[],activeSession:null,settings:{weightUnit:'kg',bodyweightUnit:'kg',defaultRestSeconds:90}});
let data = loadData();
let currentPage='today';
let historyMonth='all';
let progressExercise='';
let pickerTarget='workout';
let routineDraft=loadRoutineDraft();
let workoutClock=null;

function loadData(){
  try {
    const current=localStorage.getItem(STORE_KEY);
    if(current) return normalizeData(JSON.parse(current));
    const old=localStorage.getItem(OLD_KEY);
    if(old){const legacy=JSON.parse(old);const migrated=normalizeData({...legacy,version:2,settings:{weightUnit:'kg',bodyweightUnit:'kg',defaultRestSeconds:90}});persistData(migrated);return migrated;}
  } catch(error){console.warn('Could not read workout data',error);}
  return freshData();
}
function normalizeData(raw){
  const d={...freshData(),...raw,settings:{...freshData().settings,...(raw.settings||{})}};
  d.routines=Array.isArray(d.routines)?d.routines.map(r=>({...r,exercises:(r.exercises||[]).map(e=>({...e,id:e.id||uid(),restSeconds:e.restSeconds==null?90:Number(e.restSeconds),note:e.note||'',tutorialUrl:e.tutorialUrl||''}))})):[];
  d.workouts=Array.isArray(d.workouts)?d.workouts.map(w=>({...w,id:w.id||uid(),weightUnit:w.weightUnit||w.loadUnit||'kg',exercises:(w.exercises||[]).map(e=>({...e,id:e.id||uid(),sets:(e.sets||[]).map(s=>({type:s.type||'normal',weight:s.weight??'',reps:s.reps??'',rpe:s.rpe??'',done:!!s.done}))}))})):[];
  d.weighIns=Array.isArray(d.weighIns)?d.weighIns:[];
  d.customExercises=Array.isArray(d.customExercises)?d.customExercises:[];
  if(d.activeSession){const s=d.activeSession;s.id=s.id||uid();s.startedAt=s.startedAt||Date.now();s.weightUnit=s.weightUnit||s.loadUnit||d.settings.weightUnit;s.notes=s.notes||'';s.exercises=(s.exercises||[]).map(e=>({...e,id:e.id||uid(),restSeconds:e.restSeconds==null?90:Number(e.restSeconds),note:e.note||'',sets:(e.sets||[]).map(set=>({type:set.type||'normal',weight:set.weight??'',reps:set.reps??'',rpe:set.rpe??'',done:!!set.done}))}));}
  return d;
}
function persistData(value=data){localStorage.setItem(STORE_KEY,JSON.stringify(value));}
function persist(){persistData(data);}
function loadRoutineDraft(){try{const raw=localStorage.getItem(ROUTINE_DRAFT_KEY);return raw?JSON.parse(raw):null;}catch{return null;}}
function saveRoutineDraft(draft=readRoutineDraft()){if(!draft)return;routineDraft=draft;try{localStorage.setItem(ROUTINE_DRAFT_KEY,JSON.stringify(draft));}catch(error){console.warn('Could not save routine draft',error);}}
function clearRoutineDraft(){routineDraft=null;try{localStorage.removeItem(ROUTINE_DRAFT_KEY);}catch{}}
function escapeHtml(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function safeUrl(raw){try{const u=new URL(raw);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}}
function formatDate(value,opts={weekday:'short',month:'short',day:'numeric',year:'numeric'}){if(!value)return '';return new Date(`${value}T12:00:00`).toLocaleDateString(undefined,opts);}
function formatClock(seconds){seconds=Math.max(0,Math.floor(seconds));return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
function elapsed(s){return (s.elapsedBefore||0)+Math.max(0,Math.floor(((s.pausedAt||Date.now())-s.startedAt)/1000));}
function formatDuration(sec){const h=Math.floor(sec/3600),m=Math.floor((sec%3600)/60);return h?`${h}h ${m}m`:`${m} min`;}
function workoutVolume(session){return (session?.exercises||[]).reduce((total,e)=>total+e.sets.reduce((sum,s)=>sum+(Number(s.weight)||0)*(Number(s.reps)||0),0),0);}
function allExercises(){return [...DEFAULT_LIBRARY,...data.customExercises];}
function latestWeight(){return [...data.weighIns].sort((a,b)=>b.date.localeCompare(a.date)||(b.createdAt||0)-(a.createdAt||0))[0];}
function latestWorkoutForExercise(name,excludeId=''){
  const items=data.workouts.filter(w=>w.id!==excludeId&&w.exercises?.some(e=>e.name.toLowerCase()===name.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date)||(b.completedAt||0)-(a.completedAt||0));
  const workout=items[0];return workout?{workout,exercise:workout.exercises.find(e=>e.name.toLowerCase()===name.toLowerCase())}:null;
}
function latestWorkoutForRoutine(rid){return [...data.workouts].filter(w=>w.routineId===rid).sort((a,b)=>b.date.localeCompare(a.date)||(b.completedAt||0)-(a.completedAt||0))[0];}
function weekCount(){const from=new Date();from.setDate(from.getDate()-6);const key=localDate(from);return data.workouts.filter(w=>w.date>=key&&w.date<=todayISO()).length;}
function localDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function render(){
  document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===currentPage));
  const root=document.querySelector('#app');
  root.innerHTML=currentPage==='routines'?renderRoutines():currentPage==='history'?renderHistory():currentPage==='exercises'?renderExercises():currentPage==='workout'?renderWorkout():renderToday();
  if(currentPage==='workout')startClock();else stopClock();
}
function renderToday(){
  const weight=latestWeight(),today=todayISO(),recent=[...data.workouts].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3);
  const routineRows=data.routines.slice(0,4).map(r=>{const last=latestWorkoutForRoutine(r.id);return `<article class="routine-row"><div class="routine-row-main"><h3>${escapeHtml(r.name)}</h3><p>${r.exercises.length} exercises · ${last?`Last trained ${formatDate(last.date,{month:'short',day:'numeric'})}`:'No sessions yet'}</p></div><div class="routine-row-actions"><span class="routine-tag">${r.exercises.length} moves</span><button class="btn btn-secondary btn-small" data-start="${escapeHtml(r.id)}">Start →</button></div></article>`;}).join('');
  const hero=data.activeSession?`<section class="hero"><div class="hero-copy"><p class="eyebrow">Workout in progress</p><h2>${escapeHtml(data.activeSession.routineName)}</h2><p>Pick up where you left off. Your session is saved as you go.</p><button class="btn btn-primary" data-action="resume">Continue workout · <span data-live-clock>${formatClock(elapsed(data.activeSession))}</span></button></div><div class="hero-art">↗</div></section>`:`<section class="hero"><div class="hero-copy"><p class="eyebrow">Training log · ${formatDate(today,{weekday:'long',month:'short',day:'numeric'})}</p><h2>Ready for your next session?</h2><p>Start a routine to see your previous sets, log today’s work, and keep your progress moving.</p><button class="btn btn-primary" data-page="routines">Choose a routine <span>→</span></button></div><div class="hero-art">✳</div></section>`;
  return `<div class="heading-row"><div><p class="eyebrow">Your training space</p><h1 class="page-title">Today</h1><p class="page-subtitle">A clear view of where you are and what comes next.</p></div><div class="date-chip">${formatDate(today,{weekday:'long',month:'short',day:'numeric'})}</div></div>${hero}
    <div class="stat-grid"><div class="card stat-card"><div class="stat-value">${weekCount()}</div><div class="stat-label">workouts · last 7 days</div></div><div class="card stat-card"><div class="stat-value">${data.routines.length}</div><div class="stat-label">saved routines</div></div><div class="card stat-card"><div class="stat-value">${data.workouts.length}</div><div class="stat-label">all-time sessions</div></div></div>
    <div class="grid-two"><section><div class="section-head"><h2>Your routines</h2><button class="btn btn-quiet btn-small" data-page="routines">Manage →</button></div>${routineRows?`<div class="routine-list">${routineRows}</div>`:`<div class="empty"><div class="empty-icon">▤</div><strong>Build your first routine</strong><p>Add your exercises, set targets, notes, and tutorial links. You can keep as many routines as you need.</p><button class="btn btn-primary btn-small" data-action="new-routine">＋ Create routine</button></div>`}</section>
    <section class="card weight-card"><div><p class="eyebrow">Bodyweight</p><h2 class="card-title">Check in</h2><p class="card-note">Optional daily measurement.</p>${weight?`<div class="weight-value">${escapeHtml(weight.weight)} <span style="font-size:12px;font-weight:650">${escapeHtml(weight.unit)}</span></div><div class="weight-label">Last logged ${formatDate(weight.date,{month:'short',day:'numeric',year:'numeric'})}</div>`:`<div class="weight-value" style="color:#a1aaa3">— <span style="font-size:12px">kg / lb</span></div><div class="weight-label">No entries yet</div>`}</div><form class="weight-form" data-form="weigh-in"><input class="field" name="weight" type="number" inputmode="decimal" min="0" step="0.1" placeholder="Weight" aria-label="Bodyweight" required><select class="field" name="unit" aria-label="Weight unit" style="max-width:70px"><option ${data.settings.bodyweightUnit==='kg'?'selected':''}>kg</option><option ${data.settings.bodyweightUnit==='lb'?'selected':''}>lb</option></select><button class="btn btn-primary" type="submit">Log</button></form></section></div>
    <div class="section-head"><h2>Recent workouts</h2><button class="btn btn-quiet btn-small" data-page="history">See history →</button></div>${recent.length?`<div class="history-list">${recent.map(workoutCard).join('')}</div>`:`<div class="card"><p class="card-note" style="margin:0">Completed workouts will appear here, with every set and note saved.</p></div>`}`;
}
function workoutCard(w){const sets=(w.exercises||[]).reduce((n,e)=>n+(e.sets||[]).filter(s=>s.weight!==''||s.reps!=='').length,0);return `<article class="card history-card"><div class="history-top"><div><p class="eyebrow" style="margin-bottom:4px">${formatDate(w.date,{weekday:'short',month:'short',day:'numeric'})}</p><h3>${escapeHtml(w.routineName||w.name||'Workout')}</h3><p>${w.durationSeconds?formatDuration(w.durationSeconds)+' · ':''}${w.exercises?.length||0} exercises</p></div>${w.bodyweight?`<span class="stat-chip">${escapeHtml(w.bodyweight)} ${escapeHtml(w.bodyweightUnit||'kg')}</span>`:''}</div><div class="history-stats"><span class="stat-chip">${sets} sets logged</span><span class="stat-chip">${escapeHtml(w.weightUnit||'kg')} load</span><button class="btn btn-quiet btn-small" data-view-workout="${escapeHtml(w.id)}">Details</button></div></article>`;}
function renderRoutines(){
  const rows=data.routines.map(r=>{const last=latestWorkoutForRoutine(r.id);return `<article class="routine-row"><div class="routine-row-main"><h3>${escapeHtml(r.name)}</h3><p>${r.exercises.length} exercises${last?` · Last trained ${formatDate(last.date,{month:'short',day:'numeric'})}`:' · Ready for your first session'}</p>${r.description?`<p class="routine-notes">${escapeHtml(r.description)}</p>`:''}</div><div class="routine-row-actions"><button class="btn btn-primary btn-small" data-start="${escapeHtml(r.id)}">Start</button><button class="btn btn-secondary btn-small" data-edit-routine="${escapeHtml(r.id)}">Edit</button><button class="btn btn-quiet btn-small" data-duplicate-routine="${escapeHtml(r.id)}" title="Duplicate routine">⧉</button><button class="btn btn-quiet btn-small" data-delete-routine="${escapeHtml(r.id)}" aria-label="Delete ${escapeHtml(r.name)}">···</button></div></article>`;}).join('');
  return `<div class="heading-row"><div><p class="eyebrow">Reusable training plans</p><h1 class="page-title">Routines</h1><p class="page-subtitle">Save your program once, then run it whenever you train.</p></div><div style="display:flex;gap:7px"><button class="btn btn-secondary" data-action="start-empty">Start empty</button><button class="btn btn-primary" data-action="new-routine">＋ New routine</button></div></div>${rows?`<div class="routine-list">${rows}</div>`:`<div class="empty"><div class="empty-icon">▤</div><strong>No routines yet</strong><p>Create your first routine with exercises, target sets, exercise notes, rest timers, and video links.</p><button class="btn btn-primary" data-action="new-routine">Create your first routine</button></div>`}`;
}
function renderHistory(){
  const sessions=[...data.workouts].sort((a,b)=>b.date.localeCompare(a.date)||(b.completedAt||0)-(a.completedAt||0)).filter(w=>historyMonth==='all'||w.date.startsWith(historyMonth));
  const weightData=weightSeries(),exerciseNames=[...new Set(data.workouts.flatMap(w=>(w.exercises||[]).map(e=>e.name)))].sort();if(!exerciseNames.includes(progressExercise))progressExercise=exerciseNames[0]||'';
  return `<div class="heading-row"><div><p class="eyebrow">Training and progress</p><h1 class="page-title">History</h1><p class="page-subtitle">Review sessions, bodyweight, and exercise performance.</p></div><button class="btn btn-secondary" data-action="backup-menu">↧ Backup data</button></div>
    <div class="grid-two" style="margin-bottom:18px"><section class="card chart-card"><div class="chart-heading"><div><h3>Bodyweight trend</h3><p>${weightData.length?`${weightData.length} check-ins · latest ${escapeHtml(weightData.at(-1).label)}`:'Log bodyweight to see your trend here.'}</p></div><span class="tag">${escapeHtml(data.settings.bodyweightUnit)}</span></div>${renderLineChart(weightData)}</section><section class="card chart-card"><div class="chart-heading"><div><h3>Training consistency</h3><p>Workouts completed this week</p></div><span class="tag">7 days</span></div>${renderWeekBars()}</section></div>
    <section class="card chart-card" style="margin-bottom:18px"><div class="chart-heading"><div><h3>Exercise progress</h3><p>Best logged load per session</p></div><div class="field-inline"><span class="tag">${escapeHtml(data.settings.weightUnit)}</span><select class="field" data-exercise-progress style="max-width:200px" ${exerciseNames.length?'':'disabled'}>${exerciseNames.length?exerciseNames.map(n=>`<option ${n===(progressExercise||exerciseNames[0])?'selected':''}>${escapeHtml(n)}</option>`).join(''):'<option>No exercises logged yet</option>'}</select></div></div>${renderLineChart(exerciseSeries(progressExercise||exerciseNames[0]),'exercise')}</section>
    <div class="section-head" style="margin-top:0"><h2>Workout sessions <span class="subcount">${sessions.length}</span></h2></div><div class="filter-row"><label class="field-label" for="history-month" style="margin:0">Show</label><select class="field" id="history-month" data-history-filter><option value="all" ${historyMonth==='all'?'selected':''}>All time</option>${availableMonths().map(m=>`<option value="${m}" ${historyMonth===m?'selected':''}>${formatDate(`${m}-01`,{month:'long',year:'numeric'})}</option>`).join('')}</select></div>${sessions.length?`<div class="history-list">${sessions.map(w=>workoutCard(w)+renderWorkoutExpand(w)).join('')}</div>`:`<div class="empty"><div class="empty-icon">◷</div><strong>No workouts for this period</strong><p>Finish a session and it will be saved here.</p></div>`}
    <div class="section-head"><h2>Bodyweight entries <span class="subcount">${data.weighIns.length}</span></h2></div>${data.weighIns.length?`<div class="routine-list">${[...data.weighIns].sort((a,b)=>b.date.localeCompare(a.date)||(b.createdAt||0)-(a.createdAt||0)).slice(0,30).map(w=>`<article class="routine-row"><div class="routine-row-main"><h3>${escapeHtml(w.weight)} ${escapeHtml(w.unit)}</h3><p>${formatDate(w.date)}</p></div><button class="btn btn-quiet btn-small" data-delete-weight="${escapeHtml(w.id)}">Delete</button></article>`).join('')}</div>`:`<div class="card"><p class="card-note" style="margin:0">Your weigh-ins will be listed here.</p></div>`}`;
}
function renderWorkoutExpand(w){return `<details class="exercise-summary"><summary>Exercise details · ${escapeHtml(w.durationSeconds?formatDuration(w.durationSeconds):'session')}</summary><ul>${(w.exercises||[]).map(e=>{const done=(e.sets||[]).filter(s=>s.weight!==''||s.reps!=='');return `<li><strong>${escapeHtml(e.name)}</strong>${done.length?` — ${done.map(s=>`${s.weight?`${escapeHtml(s.weight)} ${escapeHtml(w.weightUnit||'kg')}`:''}${s.weight&&s.reps?' × ':''}${s.reps?`${escapeHtml(s.reps)} reps`:''}${s.rpe?` @ RPE ${escapeHtml(s.rpe)}`:''}`).join(', ')}`:' — no sets logged'}</li>`;}).join('')}</ul>${w.notes?`<p>${escapeHtml(w.notes)}</p>`:''}<div style="display:flex;gap:7px;margin-top:9px"><button class="btn btn-secondary btn-small" data-edit-workout="${escapeHtml(w.id)}">Edit workout</button><button class="btn btn-quiet btn-small" data-delete-workout="${escapeHtml(w.id)}">Delete</button></div></details>`;}
function availableMonths(){return [...new Set(data.workouts.map(w=>w.date.slice(0,7)).filter(Boolean))].sort().reverse();}
function weightSeries(){const rows=[...data.weighIns].sort((a,b)=>a.date.localeCompare(b.date)).slice(-10);if(!rows.length)return [];const unit=data.settings.bodyweightUnit||'kg';return rows.map(w=>({value:convertWeight(Number(w.weight),w.unit,unit),label:formatDate(w.date,{month:'short',day:'numeric'})}));}
function exerciseSeries(name){if(!name)return [];return [...data.workouts].sort((a,b)=>a.date.localeCompare(b.date)).map(w=>{const e=(w.exercises||[]).find(x=>x.name.toLowerCase()===name.toLowerCase());if(!e)return null;const loads=e.sets.filter(s=>s.weight!==''&&Number.isFinite(Number(s.weight))).map(s=>Number(s.weight));return loads.length?{value:convertWeight(Math.max(...loads),w.weightUnit||'kg',data.settings.weightUnit),label:formatDate(w.date,{month:'short',day:'numeric'})}:null;}).filter(Boolean).slice(-10);}
function convertWeight(value,from,to){if(from===to)return value;return from==='lb'?value/2.20462:value*2.20462;}
function renderLineChart(points,kind='weight'){if(points.length<2)return `<div class="empty" style="padding:17px;margin-top:13px"><p style="margin:0">${points.length?`${kind==='weight'?'One weigh-in':'One session'} logged. Add another to see a trend.`:kind==='weight'?'No measurements yet.':'No logged loads for this exercise yet.'}</p></div>`;const vals=points.map(p=>p.value),min=Math.min(...vals),max=Math.max(...vals),range=max-min||1;const coords=vals.map((v,i)=>[20+i*260/(vals.length-1),115-(v-min)*88/range]);const line=coords.map((p,i)=>`${i?'L':'M'}${p[0]},${p[1]}`).join(' ');const area=`${line} L${coords.at(-1)[0]},125 L${coords[0][0]},125 Z`;return `<div class="chart-wrap"><svg viewBox="0 0 300 130" role="img" aria-label="${kind==='weight'?'Bodyweight':'Exercise'} trend line"><path class="chart-grid" d="M12 28H290M12 68H290M12 108H290"/><path class="chart-area" d="${area}"/><path class="chart-line" d="${line}"/>${coords.map(p=>`<circle class="chart-dot" cx="${p[0]}" cy="${p[1]}" r="3.5"/>`).join('')}</svg></div><div class="chart-labels"><span>${escapeHtml(points[0].label)}</span><span>${escapeHtml(points.at(-1).label)}</span></div>`;}
function renderWeekBars(){const labels=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const date=localDate(d);labels.push({label:d.toLocaleDateString(undefined,{weekday:'narrow'}),count:data.workouts.filter(w=>w.date===date).length});}const max=Math.max(1,...labels.map(x=>x.count));return `<div class="week-bars">${labels.map(x=>`<div class="week-bar-col"><span class="week-bar-count">${x.count||''}</span><div class="week-bar-track"><i style="height:${x.count?Math.max(13,x.count/max*100):0}%"></i></div><small>${escapeHtml(x.label)}</small></div>`).join('')}</div>`;}
function renderExercises(){const list=allExercises().slice().sort((a,b)=>a.name.localeCompare(b.name));return `<div class="heading-row"><div><p class="eyebrow">Exercise catalog</p><h1 class="page-title">Exercises</h1><p class="page-subtitle">Pick from common movements or add your own.</p></div><button class="btn btn-primary" data-action="create-exercise">＋ Custom exercise</button></div><div class="library-toolbar"><input class="field" id="exercise-search" type="search" placeholder="Search exercises" aria-label="Search exercises"><select id="exercise-category" class="field" style="max-width:150px"><option value="all">All groups</option>${[...new Set(list.map(e=>e.category))].sort().map(c=>`<option>${escapeHtml(c)}</option>`).join('')}</select></div><div id="exercise-list" class="exercise-list">${list.map(libraryCard).join('')}</div>`;}
function libraryCard(e){const n=data.workouts.reduce((sum,w)=>sum+(w.exercises||[]).filter(x=>x.name.toLowerCase()===e.name.toLowerCase()).length,0);return `<article class="card library-card" data-library-name="${escapeHtml(e.name.toLowerCase())}" data-library-category="${escapeHtml(e.category)}"><div><h3>${escapeHtml(e.name)}</h3><p>${escapeHtml(e.category)} · ${n?`logged ${n} time${n===1?'':'s'}`:e.custom?'Personal exercise':'Exercise'}</p></div>${e.custom?`<button class="btn btn-quiet btn-small" data-delete-exercise="${escapeHtml(e.id)}">Remove</button>`:`<span class="tag">${escapeHtml(e.category)}</span>`}</article>`;}
function renderWorkout(){
  const s=data.activeSession;if(!s){currentPage='today';return renderToday();}
  const done=s.exercises.reduce((n,e)=>n+e.sets.filter(x=>x.done).length,0),total=s.exercises.reduce((n,e)=>n+e.sets.length,0);
  const cards=s.exercises.map((e,ei)=>renderActiveExercise(e,ei,s)).join('');
  const rest=s.restUntil&&s.restUntil>Date.now()?`<div class="rest-banner"><div><span>Rest timer</span><br><strong data-rest-clock>${formatClock((s.restUntil-Date.now())/1000)}</strong></div><div class="rest-buttons"><button data-action="rest-minus">−15 sec</button><button data-action="rest-plus">+15 sec</button><button data-action="rest-skip">Skip</button></div></div>`:'';
  return `<div class="workout-top"><div><p class="eyebrow">Live workout</p><h1 class="page-title">${escapeHtml(s.routineName)}</h1><div class="workout-meta"><span class="date-chip"><span data-live-clock>${formatClock(elapsed(s))}</span> elapsed</span><span class="date-chip">${done}/${total} sets</span><span class="date-chip">Volume <b data-live-volume>${Math.round(workoutVolume(s)).toLocaleString()}</b> ${escapeHtml(s.weightUnit)} × reps</span><label class="date-chip field-inline" style="padding:5px 8px">Date <input class="field" type="date" aria-label="Workout date" data-session-field="date" value="${escapeHtml(s.date)}" style="width:130px;padding:5px"></label><label class="date-chip field-inline" style="padding:5px 8px">BW <input class="field" type="number" inputmode="decimal" step="0.1" min="0" placeholder="—" aria-label="Bodyweight for this workout" data-session-field="bodyweight" value="${escapeHtml(s.bodyweight)}" style="width:65px;padding:5px"><select class="field" data-session-field="bodyweightUnit" aria-label="Bodyweight unit" style="width:53px;padding:5px"><option ${s.bodyweightUnit==='kg'?'selected':''}>kg</option><option ${s.bodyweightUnit==='lb'?'selected':''}>lb</option></select></label></div></div><button class="btn btn-quiet" data-action="discard-session">× End</button></div>
    <div class="workout-tools"><button class="btn btn-secondary btn-small" data-action="add-workout-exercise">＋ Add exercise</button><label class="date-chip field-inline">Load unit <select class="field" data-session-field="weightUnit" style="width:64px;padding:5px"><option ${s.weightUnit==='kg'?'selected':''}>kg</option><option ${s.weightUnit==='lb'?'selected':''}>lb</option></select></label></div>
    ${rest}${cards||`<div class="empty"><strong>Start with an exercise</strong><p>Add a movement to this session to begin logging sets.</p><button class="btn btn-primary btn-small" data-action="add-workout-exercise">＋ Add exercise</button></div>`}
    <div class="card" style="margin-top:13px"><label class="field-label" for="workout-notes">Workout notes</label><textarea id="workout-notes" class="field" data-session-field="notes" rows="2" placeholder="How did the session feel?">${escapeHtml(s.notes||'')}</textarea></div>
    <div class="session-footer"><button class="btn btn-secondary" data-action="discard-session">Discard</button><button class="btn btn-primary" data-action="finish-session">Finish workout ✓</button></div>`;
}
function renderActiveExercise(e,ei,s){
  const prior=latestWorkoutForExercise(e.name,s.editingWorkoutId||'');
  const priorSets=prior?.exercise?.sets||[];
  const lastSummary=prior?`${formatDate(prior.workout.date,{month:'short',day:'numeric'})}: ${priorSets.filter(x=>x.weight!==''||x.reps!=='').map(x=>[x.weight&&`${x.weight} ${prior.workout.weightUnit||'kg'}`,x.reps&&`${x.reps} reps`].filter(Boolean).join(' × ')).join(' · ')||'session logged'}`:'No previous sets';
  const previousRows=e.sets.map((set,si)=>{const p=priorSets[si];const prev=p&&(p.weight!==''||p.reps!=='')?`${p.weight?`${escapeHtml(p.weight)} ${escapeHtml(prior.workout.weightUnit||'kg')}`:''}${p.weight&&p.reps?' × ':''}${p.reps?`${escapeHtml(p.reps)} reps`:''}`:'';return `<div class="set-row"><span class="set-number">${si+1}</span><button class="set-type" data-cycle-type="${ei}:${si}" title="Change set type">${set.type==='normal'?'—':escapeHtml(set.type)}</button><input class="field" type="number" inputmode="decimal" min="0" step="0.5" placeholder="—" aria-label="${escapeHtml(e.name)} set ${si+1} weight" data-set-field="weight" data-exercise="${ei}" data-set="${si}" value="${escapeHtml(set.weight)}"><input class="field" type="number" inputmode="numeric" min="0" step="1" placeholder="—" aria-label="${escapeHtml(e.name)} set ${si+1} reps" data-set-field="reps" data-exercise="${ei}" data-set="${si}" value="${escapeHtml(set.reps)}"><input class="field" type="number" inputmode="decimal" min="1" max="10" step="0.5" placeholder="—" aria-label="${escapeHtml(e.name)} set ${si+1} RPE" data-set-field="rpe" data-exercise="${ei}" data-set="${si}" value="${escapeHtml(set.rpe)}"><button class="check-set ${set.done?'done':''}" data-toggle-set="${ei}:${si}" aria-label="Mark set ${si+1} ${set.done?'incomplete':'complete'}">✓</button><button class="remove-set" data-remove-set="${ei}:${si}" aria-label="Remove set ${si+1}">×</button>${prev?`<div class="previous-line" style="grid-column:2/8">Previous: ${prev}</div>`:''}</div>`;}).join('');
  const url=safeUrl(e.tutorialUrl);
  return `<article class="card exercise-card"><div class="exercise-head"><div><h3>${escapeHtml(e.name)}</h3><p>${e.sets.length} sets · Rest ${formatClock(e.restSeconds??data.settings.defaultRestSeconds)}${e.note?` · ${escapeHtml(e.note)}`:''}</p></div><div class="exercise-actions">${url?`<a href="${escapeHtml(url)}" target="_blank" rel="noopener">▶ Video</a>`:''}<button data-exercise-up="${ei}" aria-label="Move exercise up">↑</button><button data-exercise-down="${ei}" aria-label="Move exercise down">↓</button><button data-edit-rest="${ei}" aria-label="Set rest timer">⏱</button><button data-remove-exercise="${ei}" aria-label="Remove exercise">···</button></div></div><div class="previous-strip"><strong>Previous</strong><span>${escapeHtml(lastSummary)}</span>${prior?`<button class="btn btn-quiet btn-small" data-use-previous="${ei}">Use previous</button>`:''}</div><div class="set-table"><div class="set-header"><span>Set</span><span>Type</span><span>Load (${escapeHtml(s.weightUnit)})</span><span>Reps</span><span>RPE</span><span></span><span></span></div>${previousRows}<div class="set-footer"><button class="btn btn-quiet btn-small" data-add-set="${ei}">＋ Add set</button><span class="card-note">${e.sets.filter(x=>x.done).length}/${e.sets.length} complete</span></div></div></article>`;
}
function setEditorRow(ex={}){return `<div class="exercise-editor"><div><label class="field-label">Exercise</label><input class="field" name="exerciseName" value="${escapeHtml(ex.name||'')}" placeholder="e.g. Bench press" required></div><div><label class="field-label">Sets</label><input class="field" name="exerciseSets" type="number" min="1" max="40" value="${escapeHtml(ex.sets||3)}" required></div><div><label class="field-label">Rest (sec)</label><input class="field" name="exerciseRest" type="number" min="0" max="900" value="${escapeHtml(ex.restSeconds??90)}"></div><div class="url-cell"><label class="field-label">Video link</label><input class="field" name="exerciseUrl" type="url" value="${escapeHtml(ex.tutorialUrl||'')}" placeholder="YouTube URL"></div><div class="row-controls"><button type="button" class="row-move" data-row-up title="Move exercise up">↑</button><button type="button" class="row-move" data-row-down title="Move exercise down">↓</button><button type="button" class="remove-exercise" data-remove-exercise-row aria-label="Remove exercise">×</button></div><div class="exercise-note"><label class="field-label">Exercise note (optional)</label><input class="field" name="exerciseNote" value="${escapeHtml(ex.note||'')}" placeholder="e.g. Keep elbows tucked"></div></div>`;}
function openRoutineEditor(r){const routine=r||{name:'',description:'',exercises:[]};routineDraft=routine;const rows=routine.exercises.length?routine.exercises:[{name:'',sets:3,restSeconds:data.settings.defaultRestSeconds}];showModal(`<div class="modal-header"><div><h2>${routine.id?'Edit routine':'New routine'}</h2><p>Build a repeatable workout plan.</p></div><button class="icon-button" data-close>×</button></div><form data-form="routine" data-id="${escapeHtml(routine.id||'')}"><div class="form-grid"><div class="span-two"><label class="field-label">Routine name</label><input class="field" name="routineName" value="${escapeHtml(routine.name)}" placeholder="e.g. Push day A" required></div><div class="span-two"><label class="field-label">Description (optional)</label><input class="field" name="routineDescription" value="${escapeHtml(routine.description||'')}" placeholder="A short note about this session"></div></div><div class="section-head"><h2>Exercises</h2><span class="card-note">Targets can be changed mid-workout.</span></div><div id="routine-exercise-list">${rows.map(setEditorRow).join('')}</div><div style="display:flex;gap:7px;flex-wrap:wrap;margin-top:10px"><button class="btn btn-secondary btn-small" type="button" data-action="add-routine-exercise">＋ Add exercise</button><button class="btn btn-soft btn-small" type="button" data-action="pick-routine-exercise">Choose from library</button></div><div class="modal-actions"><button class="btn btn-secondary" type="button" data-close>Cancel</button><button class="btn btn-primary" type="submit">Save routine</button></div></form>`);}
function readRoutineDraft(){const f=document.querySelector('form[data-form="routine"]');if(!f)return routineDraft;return {id:f.dataset.id||undefined,name:f.querySelector('[name="routineName"]').value,description:f.querySelector('[name="routineDescription"]').value,exercises:[...f.querySelectorAll('.exercise-editor')].map(row=>({name:row.querySelector('[name="exerciseName"]').value,sets:row.querySelector('[name="exerciseSets"]').value,restSeconds:row.querySelector('[name="exerciseRest"]').value,tutorialUrl:row.querySelector('[name="exerciseUrl"]').value,note:row.querySelector('[name="exerciseNote"]').value}))};}
function showExercisePicker(target){pickerTarget=target;const list=allExercises().slice().sort((a,b)=>a.name.localeCompare(b.name));showModal(`<div class="modal-header"><div><h2>Add exercise</h2><p>Choose a common movement or your own custom exercise.</p></div><button class="icon-button" data-close>×</button></div><input id="picker-search" class="field" type="search" placeholder="Search exercise or muscle group" autofocus><div class="picker-list" id="picker-results">${list.map(pickerCard).join('')}</div><div class="modal-actions" style="justify-content:space-between"><button class="btn btn-secondary" data-action="create-exercise">＋ Create custom exercise</button><button class="btn btn-quiet" data-close>Done</button></div>`);}
function pickerCard(e){return `<button class="picker-item" data-pick-exercise="${escapeHtml(e.id)}"><span><strong>${escapeHtml(e.name)}</strong><small>${escapeHtml(e.category)}</small></span><span class="tag">Add ＋</span></button>`;}
function openBackupModal(){showModal(`<div class="modal-header"><div><h2>Backup your training data</h2><p>Download a copy or restore a backup on this device.</p></div><button class="icon-button" data-close>×</button></div><div class="card"><h3 class="card-title">Your data stays in this browser</h3><p class="card-note">Routines and logs do not sync to another device automatically. Keep a backup somewhere safe.</p></div><div class="modal-actions" style="justify-content:space-between"><button class="btn btn-secondary" data-action="restore">↑ Restore backup</button><button class="btn btn-primary" data-action="export">↓ Download backup</button></div>`);}
function showWorkoutDetails(id){const w=data.workouts.find(x=>x.id===id);if(!w)return;showModal(`<div class="modal-header"><div><p class="eyebrow">${formatDate(w.date)}</p><h2>${escapeHtml(w.routineName)}</h2><p>${w.durationSeconds?formatDuration(w.durationSeconds):'Workout'} · ${w.exercises.length} exercises</p></div><button class="icon-button" data-close>×</button></div><div class="history-list">${w.exercises.map(e=>`<article class="card"><h3 class="card-title">${escapeHtml(e.name)}</h3><p class="card-note">${e.sets.filter(s=>s.weight!==''||s.reps!=='').map((s,i)=>`Set ${i+1}: ${s.weight?`${escapeHtml(s.weight)} ${escapeHtml(w.weightUnit||'kg')}`:''}${s.weight&&s.reps?' × ':''}${s.reps?`${escapeHtml(s.reps)} reps`:''}${s.rpe?` · RPE ${escapeHtml(s.rpe)}`:''}`).join('<br>')||'No sets logged'}</p></article>`).join('')}</div>${w.notes?`<p class="card-note" style="margin-top:12px">${escapeHtml(w.notes)}</p>`:''}<div class="modal-actions"><button class="btn btn-secondary" data-edit-workout="${escapeHtml(w.id)}">Edit workout</button><button class="btn btn-primary" data-close>Close</button></div>`);}
function showModal(html){document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop" data-backdrop><section class="modal" role="dialog" aria-modal="true">${html}</section></div>`;}
function closeModal(){document.querySelector('#modal-root').innerHTML='';}
function startWorkout(routineId=null){
  if(data.activeSession&&!confirm(`Replace the current workout (${data.activeSession.routineName})?`))return;
  const routine=data.routines.find(r=>r.id===routineId);
  const weight=latestWeight();
  const exercises=(routine?.exercises||[]).map(e=>({id:e.id||uid(),name:e.name,tutorialUrl:e.tutorialUrl||'',note:e.note||'',restSeconds:e.restSeconds==null?data.settings.defaultRestSeconds:Number(e.restSeconds),sets:Array.from({length:Math.max(1,Number(e.sets)||3)},()=>({type:'normal',weight:'',reps:'',rpe:'',done:false}))}));
  data.activeSession={id:uid(),routineId:routine?.id||null,routineName:routine?.name||'Empty workout',date:todayISO(),startedAt:Date.now(),elapsedBefore:0,bodyweight:weight?.date===todayISO()?weight.weight:'',bodyweightUnit:weight?.unit||data.settings.bodyweightUnit,weightUnit:data.settings.weightUnit,notes:'',exercises,restUntil:null};
  persist();currentPage='workout';closeModal();render();window.scrollTo(0,0);
}
function finishWorkout(){const s=data.activeSession;if(!s)return;const record={...s,durationSeconds:elapsed(s),completedAt:Date.now()};delete record.restUntil;delete record.elapsedBefore;delete record.startedAt;delete record.pausedAt;delete record.editingWorkoutId;data.workouts=data.workouts.filter(w=>w.id!==s.editingWorkoutId);data.workouts.push(record);data.activeSession=null;currentPage='today';persist();render();notify('Workout saved. Great work.');}
function resumeEditWorkout(id){const w=data.workouts.find(x=>x.id===id);if(!w)return;if(data.activeSession&&!confirm('Replace the workout currently in progress?'))return;const s={...w,editingWorkoutId:w.id,startedAt:Date.now(),elapsedBefore:w.durationSeconds||0,restUntil:null};data.activeSession=s;persist();closeModal();currentPage='workout';render();window.scrollTo(0,0);}
function startClock(){stopClock();workoutClock=setInterval(()=>{const s=data.activeSession;if(!s)return;document.querySelectorAll('[data-live-clock]').forEach(el=>el.textContent=formatClock(elapsed(s)));const rest=document.querySelector('[data-rest-clock]');if(rest){const remain=Math.ceil((s.restUntil-Date.now())/1000);rest.textContent=formatClock(remain);if(remain<=0){s.restUntil=null;persist();render();notify('Rest complete. Next set when you’re ready.');}}},1000);}
function stopClock(){if(workoutClock){clearInterval(workoutClock);workoutClock=null;}}
function notify(msg){document.querySelector('.notice')?.remove();const n=document.createElement('div');n.className='notice';n.textContent=msg;document.body.append(n);setTimeout(()=>n.remove(),2400);}

document.addEventListener('input',event=>{
  const setField=event.target.closest('[data-set-field]');if(setField){const s=data.activeSession,e=s?.exercises[Number(setField.dataset.exercise)],set=e?.sets[Number(setField.dataset.set)];if(set){set[setField.dataset.setField]=setField.value;persist();const volume=document.querySelector('[data-live-volume]');if(volume)volume.textContent=Math.round(workoutVolume(s)).toLocaleString();}return;}
  const sessionField=event.target.closest('[data-session-field]');if(sessionField){data.activeSession[sessionField.dataset.sessionField]=sessionField.value;persist();return;}
  if(event.target.closest('form[data-form="routine"]')){saveRoutineDraft();return;}
  if(event.target.id==='picker-search'){const q=event.target.value.toLowerCase();document.querySelectorAll('.picker-item').forEach(item=>item.hidden=!item.textContent.toLowerCase().includes(q));return;}
  if(event.target.id==='exercise-search'||event.target.id==='exercise-category'){filterExerciseLibrary();}
});
document.addEventListener('change',event=>{
  const f=event.target.closest('[data-session-field]');if(f){data.activeSession[f.dataset.sessionField]=f.value;if(f.dataset.sessionField==='weightUnit')data.settings.weightUnit=f.value;if(f.dataset.sessionField==='bodyweightUnit')data.settings.bodyweightUnit=f.value;persist();render();return;}
  if(event.target.matches('[data-history-filter]')){historyMonth=event.target.value;render();return;}
  if(event.target.matches('[data-exercise-progress]')){progressExercise=event.target.value;render();return;}
  if(event.target.matches('#exercise-category'))filterExerciseLibrary();
});
function filterExerciseLibrary(){const q=(document.querySelector('#exercise-search')?.value||'').toLowerCase(),cat=document.querySelector('#exercise-category')?.value||'all';document.querySelectorAll('[data-library-name]').forEach(item=>{item.hidden=!(item.dataset.libraryName.includes(q)&& (cat==='all'||item.dataset.libraryCategory===cat));});}
function addExerciseToSession(ex){const s=data.activeSession;if(!s)return;s.exercises.push({id:uid(),name:ex.name,tutorialUrl:'',note:'',restSeconds:data.settings.defaultRestSeconds,sets:[{type:'normal',weight:'',reps:'',rpe:'',done:false},{type:'normal',weight:'',reps:'',rpe:'',done:false},{type:'normal',weight:'',reps:'',rpe:'',done:false}]});persist();currentPage='workout';closeModal();render();}
function createCustomExercise(){const name=prompt('Exercise name');if(!name?.trim())return;const category=prompt('Muscle group or category (for example, Back)')||'Custom';const ex={id:uid(),name:name.trim(),category:category.trim(),custom:true};data.customExercises.push(ex);persist();if(pickerTarget==='workout'){addExerciseToSession(ex);return;}if(pickerTarget==='routine'){const draft=readRoutineDraft();draft.exercises=draft.exercises.filter(item=>item.name?.trim());draft.exercises.push({name:ex.name,sets:3,restSeconds:data.settings.defaultRestSeconds,tutorialUrl:'',note:''});openRoutineEditor(draft);return;}closeModal();if(currentPage==='exercises')render();notify('Custom exercise added.');}
function exportBackup(){const payload={...data,exportedAt:new Date().toISOString(),app:'Form workout log'};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`form-workout-backup-${todayISO()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);closeModal();notify('Backup downloaded.');}

document.addEventListener('click',event=>{
  const nav=event.target.closest('[data-page]');if(nav){currentPage=nav.dataset.page;render();window.scrollTo(0,0);return;}
  const start=event.target.closest('[data-start]');if(start){startWorkout(start.dataset.start);return;}
  const edit=event.target.closest('[data-edit-routine]');if(edit){clearRoutineDraft();openRoutineEditor(data.routines.find(r=>r.id===edit.dataset.editRoutine));return;}
  const duplicate=event.target.closest('[data-duplicate-routine]');if(duplicate){const r=data.routines.find(x=>x.id===duplicate.dataset.duplicateRoutine);if(r){const copy=JSON.parse(JSON.stringify(r));copy.id=uid();copy.name=`${r.name} copy`;copy.createdAt=Date.now();copy.exercises=copy.exercises.map(e=>({...e,id:uid()}));data.routines.push(copy);persist();render();notify('Routine duplicated.');}return;}
  const delRoutine=event.target.closest('[data-delete-routine]');if(delRoutine){const r=data.routines.find(x=>x.id===delRoutine.dataset.deleteRoutine);if(r&&confirm(`Delete “${r.name}”? Completed workout history will remain.`)){data.routines=data.routines.filter(x=>x.id!==r.id);persist();render();notify('Routine deleted.');}return;}
  const view=event.target.closest('[data-view-workout]');if(view){showWorkoutDetails(view.dataset.viewWorkout);return;}
  const editWorkout=event.target.closest('[data-edit-workout]');if(editWorkout){resumeEditWorkout(editWorkout.dataset.editWorkout);return;}
  const deleteWorkout=event.target.closest('[data-delete-workout]');if(deleteWorkout){const id=deleteWorkout.dataset.deleteWorkout;if(confirm('Delete this saved workout from history?')){data.workouts=data.workouts.filter(w=>w.id!==id);persist();closeModal();render();notify('Workout deleted.');}return;}
  const deleteWeight=event.target.closest('[data-delete-weight]');if(deleteWeight){data.weighIns=data.weighIns.filter(w=>w.id!==deleteWeight.dataset.deleteWeight);persist();render();return;}
  const deleteExercise=event.target.closest('[data-delete-exercise]');if(deleteExercise){data.customExercises=data.customExercises.filter(x=>x.id!==deleteExercise.dataset.deleteExercise);persist();render();return;}
  const pick=event.target.closest('[data-pick-exercise]');if(pick){const ex=allExercises().find(x=>x.id===pick.dataset.pickExercise);if(!ex)return;if(pickerTarget==='workout'){addExerciseToSession(ex);}else if(pickerTarget==='routine'){const draft=readRoutineDraft();draft.exercises=draft.exercises.filter(item=>item.name?.trim());draft.exercises.push({name:ex.name,sets:3,restSeconds:data.settings.defaultRestSeconds,tutorialUrl:'',note:''});openRoutineEditor(draft);}return;}
  const close=event.target.closest('[data-close]');if(close){if(close.closest('.modal')?.querySelector('form[data-form="routine"]'))clearRoutineDraft();else if(pickerTarget==='routine'&&routineDraft){openRoutineEditor(routineDraft);return;}closeModal();return;}
  if(event.target.matches('[data-backdrop]')){closeModal();return;}
  const action=event.target.closest('[data-action]')?.dataset.action;
  if(action==='new-routine'){clearRoutineDraft();openRoutineEditor();return;}
  if(action==='resume'){currentPage='workout';render();return;}
  if(action==='start-empty'){startWorkout();return;}
  if(action==='add-routine-exercise'){document.querySelector('#routine-exercise-list')?.insertAdjacentHTML('beforeend',setEditorRow({sets:3,restSeconds:data.settings.defaultRestSeconds}));saveRoutineDraft();return;}
  if(action==='pick-routine-exercise'){saveRoutineDraft(readRoutineDraft());showExercisePicker('routine');return;}
  if(action==='add-workout-exercise'){showExercisePicker('workout');return;}
  if(action==='create-exercise'){if(currentPage==='exercises'&&!document.querySelector('#picker-search'))pickerTarget='library';createCustomExercise();return;}
  if(action==='backup-menu'){openBackupModal();return;}
  if(action==='export'){exportBackup();return;}
  if(action==='restore'){closeModal();document.querySelector('#restore-file').click();return;}
  if(action==='finish-session'){finishWorkout();return;}
  if(action==='discard-session'){if(confirm('Discard this workout? It will not be saved in history.')){data.activeSession=null;persist();currentPage='today';render();notify('Workout discarded.');}return;}
  if(action==='rest-skip'){data.activeSession.restUntil=null;persist();render();return;}
  if(action==='rest-plus'||action==='rest-minus'){data.activeSession.restUntil=Math.max(Date.now(),data.activeSession.restUntil+(action==='rest-plus'?15000:-15000));persist();render();return;}
  const toggle=event.target.closest('[data-toggle-set]');if(toggle){const [ei,si]=toggle.dataset.toggleSet.split(':').map(Number),set=data.activeSession?.exercises[ei]?.sets[si];if(set){set.done=!set.done;let personalBest=false;if(set.done&&Number(set.weight)>0){const previousLoads=data.workouts.filter(w=>w.id!==data.activeSession.editingWorkoutId).flatMap(w=>(w.exercises||[]).filter(e=>e.name.toLowerCase()===data.activeSession.exercises[ei].name.toLowerCase()).flatMap(e=>e.sets.map(x=>convertWeight(Number(x.weight)||0,w.weightUnit||'kg',data.activeSession.weightUnit))));personalBest=Number(set.weight)>Math.max(0,...previousLoads);}if(set.done){const sec=data.activeSession.exercises[ei].restSeconds??data.settings.defaultRestSeconds;data.activeSession.restUntil=sec>0?Date.now()+sec*1000:null;}persist();render();if(personalBest)notify('New best load for '+data.activeSession.exercises[ei].name+'!');}return;}
  const addSet=event.target.closest('[data-add-set]');if(addSet){data.activeSession.exercises[Number(addSet.dataset.addSet)].sets.push({type:'normal',weight:'',reps:'',rpe:'',done:false});persist();render();return;}
  const usePrevious=event.target.closest('[data-use-previous]');if(usePrevious){const ei=Number(usePrevious.dataset.usePrevious),exercise=data.activeSession.exercises[ei],prior=latestWorkoutForExercise(exercise.name,data.activeSession.editingWorkoutId||'');if(prior){exercise.sets.forEach((set,i)=>{const previous=prior.exercise.sets[i];if(previous){const oldWeight=Number(previous.weight),converted=convertWeight(oldWeight,prior.workout.weightUnit||'kg',data.activeSession.weightUnit);set.weight=previous.weight===''?'':String(prior.workout.weightUnit===data.activeSession.weightUnit?previous.weight:converted.toFixed(1));set.reps=previous.reps;set.rpe=previous.rpe;}});persist();render();notify('Previous set values added.');}return;}
  const removeSet=event.target.closest('[data-remove-set]');if(removeSet){const [ei,si]=removeSet.dataset.removeSet.split(':').map(Number);data.activeSession.exercises[ei].sets.splice(si,1);persist();render();return;}
  const cycle=event.target.closest('[data-cycle-type]');if(cycle){const [ei,si]=cycle.dataset.cycleType.split(':').map(Number),types=['normal','warmup','dropset','failure'];const set=data.activeSession.exercises[ei].sets[si];set.type=types[(types.indexOf(set.type)+1)%types.length];persist();render();return;}
  const moveUp=event.target.closest('[data-exercise-up]');if(moveUp){const i=Number(moveUp.dataset.exerciseUp),a=data.activeSession.exercises;if(i>0)[a[i-1],a[i]]=[a[i],a[i-1]];persist();render();return;}
  const moveDown=event.target.closest('[data-exercise-down]');if(moveDown){const i=Number(moveDown.dataset.exerciseDown),a=data.activeSession.exercises;if(i<a.length-1)[a[i+1],a[i]]=[a[i],a[i+1]];persist();render();return;}
  const editRest=event.target.closest('[data-edit-rest]');if(editRest){const i=Number(editRest.dataset.editRest),e=data.activeSession.exercises[i],value=prompt('Rest timer for this exercise, in seconds. Enter 0 to turn it off.',String(e.restSeconds??data.settings.defaultRestSeconds));if(value!==null){e.restSeconds=Math.max(0,Number(value)||0);persist();render();}return;}
  const removeExercise=event.target.closest('[data-remove-exercise]');if(removeExercise){const i=Number(removeExercise.dataset.removeExercise);if(confirm(`Remove ${data.activeSession.exercises[i].name} from this workout?`)){data.activeSession.exercises.splice(i,1);persist();render();}return;}
  const removeRow=event.target.closest('[data-remove-exercise-row]');if(removeRow){removeRow.closest('.exercise-editor').remove();return;}
  const rowUp=event.target.closest('[data-row-up]');if(rowUp){const row=rowUp.closest('.exercise-editor'),prev=row?.previousElementSibling;if(prev?.classList.contains('exercise-editor'))row.parentElement.insertBefore(row,prev);return;}
  const rowDown=event.target.closest('[data-row-down]');if(rowDown){const row=rowDown.closest('.exercise-editor'),next=row?.nextElementSibling;if(next?.classList.contains('exercise-editor'))row.parentElement.insertBefore(next,row);return;}
});

document.addEventListener('submit',event=>{
  const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();
  if(form.dataset.form==='weigh-in'){
    const fd=new FormData(form),weight=String(fd.get('weight')||'').trim(),unit=String(fd.get('unit')||'kg');if(!weight)return;
    const entry={id:uid(),date:todayISO(),weight,unit,createdAt:Date.now()};data.weighIns.push(entry);data.settings.bodyweightUnit=unit;
    if(data.activeSession&&data.activeSession.date===entry.date){data.activeSession.bodyweight=weight;data.activeSession.bodyweightUnit=unit;}
    persist();render();notify('Bodyweight logged.');return;
  }
  if(form.dataset.form==='routine'){
    const fd=new FormData(form),exercises=[...form.querySelectorAll('.exercise-editor')].map(row=>({id:uid(),name:row.querySelector('[name="exerciseName"]').value.trim(),sets:Math.max(1,Number(row.querySelector('[name="exerciseSets"]').value)||3),restSeconds:Math.max(0,Number(row.querySelector('[name="exerciseRest"]').value)||0),tutorialUrl:safeUrl(row.querySelector('[name="exerciseUrl"]').value.trim()),note:row.querySelector('[name="exerciseNote"]').value.trim()})).filter(e=>e.name);
    if(!exercises.length){notify('Add at least one exercise.');return;}
    const rid=form.dataset.id,old=data.routines.find(r=>r.id===rid),routine={id:rid||uid(),name:String(fd.get('routineName')).trim(),description:String(fd.get('routineDescription')||'').trim(),exercises,createdAt:old?.createdAt||Date.now(),updatedAt:Date.now()};
    if(rid)data.routines=data.routines.map(r=>r.id===rid?routine:r);else data.routines.push(routine);
    persist();closeModal();clearRoutineDraft();render();notify(rid?'Routine updated.':'Routine saved.');
  }
});

document.querySelector('#restore-file').addEventListener('change',async event=>{
  const file=event.target.files?.[0];if(!file)return;
  try{const parsed=JSON.parse(await file.text());if(!Array.isArray(parsed.routines)||!Array.isArray(parsed.workouts)||!Array.isArray(parsed.weighIns))throw new Error('This file does not look like a Form backup.');if(!confirm('Restore this backup? It will replace the data saved in this browser.'))return;data=normalizeData(parsed);persist();currentPage='today';render();notify('Backup restored.');}
  catch(error){alert(error.message||'Could not read that backup file.');}
  finally{event.target.value='';}
});

render();
if(routineDraft)openRoutineEditor(routineDraft);
if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')saveRoutineDraft();});
window.addEventListener('pagehide',()=>saveRoutineDraft());
